import { createContext, useContext } from "solid-js";
export const AnimatePresenceContext = createContext(null);
export function AnimatePresenceProvider(props) {
    return (<AnimatePresenceContext.Provider value={props.value}>
      {props.children}
    </AnimatePresenceContext.Provider>);
}
export function createPresenceState(config) {
    return {
        id: config.id,
        isPresent: config.isPresent,
        initial: config.initial,
        custom: config.custom || (() => undefined),
        onExitComplete: config.onExitComplete,
        register: config.register || (() => () => { }),
    };
}
export function usePresenceInternal() {
    return useContext(AnimatePresenceContext);
}
